      solution: "import json\nfrom dataclasses import dataclass\n\nOPPOSITE = {\"north\": \"south\", \"south\": \"north\", \"east\": \"west\", \"west\": \"east\"}\n\n\n@dataclass\nclass Item:\n    name: str\n    description: str\n\n\nclass Room:\n    def __init__(self, name, description):\n        self.name = name\n        self.description = description\n        self.exits = {}\n        self.items = []\n        self.locked = {}\n\n    def describe(self):\n        lines = [self.name, self.description, \"Exits: \" + (\", \".join(sorted(self.exits)) or \"none\")]\n        if self.items:\n            lines.append(\"You see: \" + \", \".join(item.name for item in self.items))\n        return \"\\n\".join(lines)\n\n    def connect(self, other, direction):\n        self.exits[direction] = other\n        other.exits[OPPOSITE[direction]] = self\n\n\ndef find(items, name):\n    for item in items:\n        if item.name.lower() == name.lower():\n            return item\n    return None\n\n\nclass Player:\n    def __init__(self, room):\n        self.room = room\n        self.inventory = []\n\n    def move(self, direction):\n        if direction not in self.room.exits:\n            raise ValueError(\"You can't go that way.\")\n        if direction in self.room.locked:\n            raise ValueError(\"The door is locked.\")\n        self.room = self.room.exits[direction]\n        return self.room\n\n    def take(self, name):\n        item = find(self.room.items, name)\n        if item is None:\n            return f\"There is no {name} here.\"\n        self.room.items.remove(item)\n        self.inventory.append(item)\n        return f\"You take the {item.name}.\"\n\n    def drop(self, name):\n        item = find(self.inventory, name)\n        if item is None:\n            return f\"You don't have a {name}.\"\n        self.inventory.remove(item)\n        self.room.items.append(item)\n        return f\"You drop the {item.name}.\"\n\n    def use(self, name):\n        item = find(self.inventory, name)\n        if item is None:\n            return f\"You don't have a {name}.\"\n        for direction, key in self.room.locked.items():\n            if key == item.name:\n                del self.room.locked[direction]\n                return f\"You unlock the door to the {direction} with the {item.name}.\"\n        return \"Nothing happens.\"\n\n\nSHORT_DIRECTIONS = {\"n\": \"north\", \"s\": \"south\", \"e\": \"east\", \"w\": \"west\"}\nVERBS = {\"get\": \"take\", \"grab\": \"take\", \"l\": \"look\", \"i\": \"inventory\", \"inv\": \"inventory\", \"walk\": \"go\", \"q\": \"quit\", \"x\": \"examine\"}\n\n\ndef parse(command):\n    words = [w for w in command.lower().split() if w not in (\"the\", \"a\", \"an\")]\n    if not words:\n        return (\"\", \"\")\n    verb, noun = words[0], \" \".join(words[1:])\n    if verb in SHORT_DIRECTIONS:\n        return (\"go\", SHORT_DIRECTIONS[verb])\n    if verb in OPPOSITE:\n        return (\"go\", verb)\n    verb = VERBS.get(verb, verb)\n    if verb == \"go\":\n        noun = SHORT_DIRECTIONS.get(noun, noun)\n    return (verb, noun)\n\n\ndef build_world():\n    hall = Room(\"Hall\", \"A dusty entrance hall.\")\n    kitchen = Room(\"Kitchen\", \"Pots and pans everywhere.\")\n    library = Room(\"Library\", \"Shelves of old books.\")\n    garden = Room(\"Garden\", \"Sunlight at last! A fountain bubbles.\")\n    hall.connect(library, \"north\")\n    hall.connect(kitchen, \"east\")\n    library.connect(garden, \"north\")\n    library.locked[\"north\"] = \"key\"\n    kitchen.items.append(Item(\"lamp\", \"A brass lamp, still working.\"))\n    library.items.append(Item(\"key\", \"A small iron key.\"))\n    garden.items.append(Item(\"treasure\", \"A chest of gold coins.\"))\n    return {room.name: room for room in (hall, kitchen, library, garden)}\n\n\nclass Game:\n    def __init__(self):\n        self.rooms = build_world()\n        self.player = Player(self.rooms[\"Hall\"])\n        self.over = False\n\n    def handle(self, command):\n        verb, noun = parse(command)\n        player = self.player\n        if verb == \"look\":\n            return player.room.describe()\n        if verb == \"go\":\n            try:\n                return player.move(noun).describe()\n            except ValueError as e:\n                return str(e)\n        if verb == \"take\":\n            reply = player.take(noun)\n            if find(player.inventory, \"treasure\"):\n                self.over = True\n                reply += \"\\nYou found the treasure! You win!\"\n            return reply\n        if verb == \"drop\":\n            return player.drop(noun)\n        if verb == \"use\":\n            return player.use(noun)\n        if verb == \"inventory\":\n            return \"You carry: \" + (\", \".join(item.name for item in player.inventory) or \"nothing\")\n        if verb == \"examine\":\n            item = find(player.inventory + player.room.items, noun)\n            return item.description if item else f\"You see no {noun} here.\"\n        if verb == \"quit\":\n            self.over = True\n            return \"Goodbye!\"\n        return \"I don't understand that.\"\n",
